/**
 * Jest config for the benchmark regression gate (issue #1031).
 *
 * The Go benchmark pipeline (`go test -bench` + benchstat baseline comparison)
 * was retired together with the abandoned Go backend migration. The TypeScript
 * gate is tests/integration/low_end_device_performance.test.ts.
 *
 * It is intentionally limited to that file:
 * - It needs no Nakama/PostgreSQL stack, so the "Benchmark Regression"
 *   workflow can run it without services.
 * - It DOES require a real measurement snapshot generated by a headless Godot
 *   run of the client (issue #1073): the workflow runs
 *   scripts/run-headless-performance-benchmark.sh first; locally do the same
 *   (requires godot4). Without the snapshot the gate fails by design.
 * - Thresholds come from tests/fixtures/performance/performance-targets.json
 *   (single source of truth, mirrored in docs/PERFORMANCE.md).
 * - tests/integration/performance_smoke.test.ts DOES need the live stack and is
 *   covered by the integration job in ci.yml — do not add it here.
 *
 * maxWorkers: 1 keeps timing measurements stable (no parallel CPU contention).
 */
const base = require('./jest.config.js');

module.exports = {
  ...base,
  roots: ['<rootDir>/tests'],
  testMatch: ['**/tests/integration/low_end_device_performance.test.ts'],
  collectCoverage: false,
  passWithNoTests: false,
  maxWorkers: 1,
  testTimeout: 60000,
};
